/**
 * OV-7b oracle: `agentwrangler statusline` must print exactly what the operator's hand-tuned
 * ~/.claude/statusline-command.sh prints (ANSI included) and write the same limits file.
 *
 * The expected values in test/fixtures/statusline/golden/ were generated by RUNNING THE OPERATOR'S
 * SCRIPT (bash + jq) on these payloads (AW_STATUSLINE_REGEN=1), not by this implementation. When the
 * script and bash+jq are present locally the same comparison also runs live.
 */

import { execFileSync, spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { runStatusline } from "../../src/cli/statusline.js";
import { CASES, type Tree, buildTree, expand } from "../fixtures/statusline/cases.js";

const GOLDEN = path.join(__dirname, "..", "fixtures", "statusline", "golden");
const SCRIPT = path.join(os.homedir(), ".claude", "statusline-command.sh");
const has = (cmd: string, args: string[]) => {
  try {
    execFileSync(cmd, args, { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
};
const canRunScript =
  fs.existsSync(SCRIPT) && has("bash", ["--version"]) && has("jq", ["--version"]);
const ESC = new RegExp(`${String.fromCharCode(27)}\\[[0-9;]*m`, "g");
const strip = (s: string) => s.replace(ESC, "");

let tmp: string;
let tree: Tree;
const nowMs = Date.now();
const nowSec = Math.floor(nowMs / 1000);

beforeAll(() => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), "aw-sl-oracle-"));
  tree = buildTree(path.join(tmp, "tree"));
});
afterAll(() => fs.rmSync(tmp, { recursive: true, force: true }));

function ours(payload: string): { out: string; limits: unknown } {
  const home = fs.mkdtempSync(path.join(tmp, "home-"));
  const out = runStatusline({ stdin: payload, home, nowMs });
  const f = path.join(home, ".agentwrangler", "statusline-limits.json");
  return { out, limits: fs.existsSync(f) ? withoutAt(fs.readFileSync(f, "utf8")) : null };
}

/** Parse the limits file, drop `at`, and express epoch resets_at as an offset from this run's "now". */
function withoutAt(json: string): unknown {
  const o = JSON.parse(json) as {
    at?: number | undefined;
    rate_limits: Record<string, { resets_at: unknown }>;
  };
  expect(typeof o.at).toBe("number");
  o.at = undefined;
  for (const w of Object.values(o.rate_limits)) {
    if (typeof w.resets_at === "number") w.resets_at = `now+${w.resets_at - nowSec}`;
    else if (typeof w.resets_at === "string") {
      w.resets_at = `now+${Math.round(Date.parse(w.resets_at) - nowSec * 1000)}ms`;
    }
  }
  return JSON.parse(JSON.stringify(o));
}

function viaScript(payload: string): { out: string; limits: unknown } {
  const home = fs.mkdtempSync(path.join(tmp, "shome-"));
  const r = spawnSync("bash", [SCRIPT], {
    input: payload,
    encoding: "utf8",
    env: { ...process.env, HOME: home },
  });
  const f = path.join(home, ".agentwrangler", "statusline-limits.json");
  return { out: r.stdout, limits: fs.existsSync(f) ? withoutAt(fs.readFileSync(f, "utf8")) : null };
}

const goldenOut = (n: string) => path.join(GOLDEN, `${n}.out.txt`);
const goldenLimits = (n: string) => path.join(GOLDEN, `${n}.limits.json`);

describe("statusline oracle: golden output from the operator's script", () => {
  for (const c of CASES) {
    it(`${c.name}: identical text (ANSI included) and limits file`, () => {
      const { out, limits } = ours(expand(c, tree, nowSec));
      expect(out).toBe(fs.readFileSync(goldenOut(c.name), "utf8"));
      const gl = fs.existsSync(goldenLimits(c.name))
        ? (JSON.parse(fs.readFileSync(goldenLimits(c.name), "utf8")) as unknown)
        : null;
      expect(limits).toEqual(gl);
    });
  }

  it("covers the required shapes (guards against an emptied fixture set)", () => {
    expect(CASES.length).toBeGreaterThanOrEqual(4);
    const named = fs.readFileSync(goldenOut("full"), "utf8");
    expect(strip(named)).toBe(
      "Opus 5.5 | AgentWrangler | feat/statusline-limits | ctx [####------] 42% 85k | 5h:23% 1h48m  7d:81% 2d11h | ~$3.20 1h23m",
    );
  });
});

describe.skipIf(!canRunScript)("statusline oracle: live against the operator's script", () => {
  for (const c of CASES) {
    it(`${c.name}: matches the script right now`, () => {
      const payload = expand(c, tree, nowSec);
      expect(ours(payload)).toEqual(viaScript(payload));
    });
  }
});

describe.skipIf(!(canRunScript && process.env.AW_STATUSLINE_REGEN === "1"))("regen goldens", () => {
  it("writes golden files from the operator's script", () => {
    fs.mkdirSync(GOLDEN, { recursive: true });
    for (const c of CASES) {
      const home = fs.mkdtempSync(path.join(tmp, "rhome-"));
      const r = spawnSync("bash", [SCRIPT], {
        input: expand(c, tree, nowSec),
        encoding: "utf8",
        env: { ...process.env, HOME: home },
      });
      fs.writeFileSync(goldenOut(c.name), r.stdout);
      const f = path.join(home, ".agentwrangler", "statusline-limits.json");
      fs.rmSync(goldenLimits(c.name), { force: true });
      if (fs.existsSync(f))
        fs.writeFileSync(
          goldenLimits(c.name),
          JSON.stringify(withoutAt(fs.readFileSync(f, "utf8")), null, 2),
        );
    }
  });
});
